  `car_type` varchar(255) NOT NULL,
  `daily_rate` double DEFAULT NULL,
  `effective_from` date DEFAULT NULL,
  `effective_to` date DEFAULT NULL,
  `image_url` varchar(255) DEFAULT NULL,
  `monthly_rate` double DEFAULT NULL,
  `weekly_rate` double DEFAULT NULL,
  `hub_id` int NOT NULL,
  PRIMARY KEY (`car_type_id`),
  KEY `FKomolwgu8w7v1nd7fg2h2fdvjx` (`hub_id`),
  CONSTRAINT `FKomolwgu8w7v1nd7fg2h2fdvjx` FOREIGN KEY (`hub_id`) REFERENCES `hub` (`hub_id`)
) ENGINE=InnoDB AUTO_INCREMENT=606 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
